//------------------------------------------------------------------------------
// yapp_input_fsm.sv -- YAPP input port state machine.
//
// Receives one packet at a time on in_data / in_data_vld / in_suspend:
//   IDLE    : header {length[5:0], addr[1:0]} -> latch addr/len, decide drop
//   PAYLOAD : `length` payload bytes
//   PARITY  : parity byte, report the packet to the register block
//
// Owns the drop decision, the in_suspend back-pressure, the FIFO push control,
// the running parity and the "ROUTER DROPS PACKET" messages. It does not own
// any register visible on HBUS: counters, mem_size_reg and yapp_pkt_mem live in
// yapp_hbus_regs and are updated through the pkt_* / pkt_mem_* ports, which are
// combinational so the register block updates at the same clock edge as the
// FSM itself.
//------------------------------------------------------------------------------

`timescale 1ns/1ns

module yapp_input_fsm (
  input  logic       clock,
  input  logic       reset,
  // YAPP input port
  input  logic [7:0] in_data,
  input  logic       in_data_vld,
  output logic       in_suspend,
  // Live register fields (yapp_hbus_regs)
  input  logic [5:0] maxpktsize,
  input  logic       router_en,
  // Output channel FIFOs
  input  logic [2:0] fifo_full,
  output logic [2:0] fifo_push,
  output logic [7:0] fifo_din,
  // End-of-packet report (valid in the cycle the parity byte is accepted and
  // the packet was received with router_en set)
  output logic       pkt_done,
  output logic [1:0] pkt_addr,
  output logic [5:0] pkt_len,
  output logic       pkt_parity_err,
  output logic       pkt_oversized,
  // Packet memory write port (header -> 0, payload byte -> byte_cnt+1)
  output logic       pkt_mem_we,
  output logic [5:0] pkt_mem_addr,
  output logic [7:0] pkt_mem_wdata
);

  typedef enum logic [1:0] {IDLE, PAYLOAD, PARITY} state_e;

  state_e     state;
  logic [1:0] cur_addr;      // address of the packet being received
  logic [5:0] cur_len;       // payload length of the packet being received
  logic [5:0] byte_cnt;      // payload bytes accepted so far
  logic [7:0] parity_acc;    // running XOR of header + payload
  logic       cur_drop;      // packet will not be forwarded
  logic       cur_oversized;
  logic       cur_enabled;   // router_en was set when the header arrived

  // Header decode (valid while state == IDLE and in_data_vld == 1)
  wire [1:0] hdr_addr   = in_data[1:0];
  wire [5:0] hdr_len    = in_data[7:2];
  wire       hdr_ovs    = (hdr_len > maxpktsize);
  wire       hdr_drop   = !router_en || hdr_ovs || (hdr_addr == 2'd3);

  // Target FIFO is full -> ask the driver to hold the current byte.
  // Dropped packets are consumed without FIFO space, so never suspended.
  always_comb begin
    case (state)
      IDLE:    in_suspend = in_data_vld && !hdr_drop && fifo_full[hdr_addr];
      default: in_suspend = !cur_drop && fifo_full[cur_addr];
    endcase
  end

  // A byte is accepted whenever the DUT is not suspending the input
  wire accept = !in_suspend;

  // FIFO push control
  always_comb begin
    fifo_push = 3'b000;
    fifo_din  = in_data;
    case (state)
      IDLE:    if (in_data_vld && accept && !hdr_drop) fifo_push[hdr_addr] = 1'b1;
      PAYLOAD: if (in_data_vld && accept && !cur_drop) fifo_push[cur_addr] = 1'b1;
      PARITY:  if (accept && !cur_drop)                fifo_push[cur_addr] = 1'b1;
      default: ;
    endcase
  end

  // Packet memory write port
  //   header       -> yapp_pkt_mem[0]          if router_en   (live register value)
  //   payload byte -> yapp_pkt_mem[byte_cnt+1] if cur_enabled (value latched at header)
  always_comb begin
    pkt_mem_we    = 1'b0;
    pkt_mem_addr  = 6'd0;
    pkt_mem_wdata = in_data;
    case (state)
      IDLE:    if (in_data_vld && accept && router_en) begin
                 pkt_mem_we   = 1'b1;
                 pkt_mem_addr = 6'd0;
               end
      PAYLOAD: if (in_data_vld && accept && cur_enabled) begin
                 pkt_mem_we   = 1'b1;
                 pkt_mem_addr = byte_cnt + 6'd1;
               end
      default: ;
    endcase
  end

  // End-of-packet report to the register block (counters, mem_size_reg) and
  // to the error timer. Only packets received with router_en set are reported.
  assign pkt_done       = (state == PARITY) && accept && cur_enabled;
  assign pkt_addr       = cur_addr;
  assign pkt_len        = cur_len;
  assign pkt_parity_err = (in_data != parity_acc);
  assign pkt_oversized  = cur_oversized;

  // Main FSM
  always_ff @(posedge clock or posedge reset) begin
    if (reset) begin
      state         <= IDLE;
      cur_addr      <= 2'd0;
      cur_len       <= 6'd0;
      byte_cnt      <= 6'd0;
      parity_acc    <= 8'd0;
      cur_drop      <= 1'b0;
      cur_oversized <= 1'b0;
      cur_enabled   <= 1'b0;
    end else begin
      case (state)
        //------------------------------------------------------------------
        IDLE: begin
          if (in_data_vld && accept) begin
            cur_addr      <= hdr_addr;
            cur_len       <= hdr_len;
            byte_cnt      <= 6'd0;
            parity_acc    <= in_data;
            cur_drop      <= hdr_drop;
            cur_oversized <= hdr_ovs;
            cur_enabled   <= router_en;
            state <= PAYLOAD;
          end
        end
        //------------------------------------------------------------------
        PAYLOAD: begin
          if (in_data_vld && accept) begin
            parity_acc <= parity_acc ^ in_data;
            byte_cnt <= byte_cnt + 6'd1;
            if (byte_cnt + 6'd1 == cur_len) begin
              state <= PARITY;
            end
          end
        end
        //------------------------------------------------------------------
        PARITY: begin
          if (accept) begin
            state <= IDLE;
            if (cur_enabled) begin
              if (cur_drop) begin
                $display("%0t ROUTER DROPS PACKET addr=%0d length=%0d (%s)", $time,
                         cur_addr, cur_len,
                         (cur_addr == 2'd3) ? "illegal address" : "length > maxpktsize");
              end
            end else begin
              $display("%0t ROUTER DROPS PACKET addr=%0d length=%0d (router disabled)",
                       $time, cur_addr, cur_len);
            end
          end
        end
        //------------------------------------------------------------------
        default: state <= IDLE;
      endcase
    end
  end

endmodule : yapp_input_fsm

files.yapp_project/rtl/yapp_output_channel.sv:
//------------------------------------------------------------------------------
// yapp_output_channel.sv -- one router output channel: a 16-byte FIFO plus the
// channel handshake towards the receiver.
//
//   data_vld : FIFO has data, the head byte is on `data`
//   pop      : receiver released `suspend` while a byte was presented
//
// Nothing is registered on the output side: the FIFO head is on the bus as long
// as the FIFO is not empty, and the receiver's `suspend` directly gates the pop,
// so a new byte appears on every rising edge while `suspend` is low.
//------------------------------------------------------------------------------

`timescale 1ns/1ns

module yapp_output_channel (
  input  logic       clock,
  input  logic       reset,
  // From the input FSM
  input  logic       push,
  input  logic [7:0] din,
  // Channel port
  input  logic       suspend,
  output logic [7:0] data,
  output logic       data_vld,
  // Back-pressure to the input FSM
  output logic       full
);

  logic empty;
  logic pop;

  yapp_fifo #(.DEPTH(16), .WIDTH(8)) u_fifo (
    .clock (clock),
    .reset (reset),
    .push  (push),
    .din   (din),
    .pop   (pop),
    .dout  (data),
    .empty (empty),
    .full  (full)
  );

  assign data_vld = !empty;
  assign pop      = !empty && !suspend;

endmodule : yapp_output_channel

files.yapp_project/rtl/yapp_router.sv:
//------------------------------------------------------------------------------
// yapp_router.sv -- YAPP packet router (Design Under Test), top level
//
// Written from the course specification ("Project Overview" of the Cadence
// SystemVerilog Accelerated Verification Using UVM training). This is a clean
// re-implementation for teaching: readable, no vendor-specific constructs.
// The top level only wires the four kinds of sub-modules (one module per file):
//
//   yapp_input_fsm      u_input_fsm   input port FSM, drop decision, FIFO push
//   yapp_output_channel g_ch[x].u_ch  16-byte FIFO + channel handshake (x = 0..2)
//   yapp_hbus_regs      u_regs        all registers/memories + HBUS host port
//   yapp_error_timer    u_error_timer `error` pulse 1..10 cycles after bad parity
//
// Function
// --------
// * One YAPP input port (in_data / in_data_vld / in_suspend). A packet is
//     byte 0        : header  = {length[5:0], addr[1:0]}
//     byte 1..N     : payload (N == length, 1..63)
//     byte N+1      : parity  = even bitwise parity (XOR) of header + payload
// * Three output channels (data_x / data_vld_x / suspend_x), each fed by a
//   16-byte FIFO. The packet is routed to channel `addr` (0, 1 or 2).
// * HBUS host port (hdata / haddr / hen / hwr_rd) gives synchronous access to
//   the registers and memories (map in yapp_hbus_regs.sv).
//
// Timing (all edges are clock edges)
// ----------------------------------
// * All DUT inputs are driven by the testbench on the FALLING edge and sampled
//   by the DUT on the RISING edge.
// * YAPP input: a byte on in_data is accepted at a rising edge when the target
//   FIFO is not full. When it IS full the DUT asserts in_suspend and the driver
//   must hold the byte unchanged until in_suspend drops.
// * Channel output: data_vld_x is high while a byte is presented on data_x.
//   The receiver reads the byte on a falling edge and de-asserts suspend_x on
//   that same falling edge; at the next rising edge the router pops the FIFO
//   and presents the next byte.
// * HBUS write : hen=1, hwr_rd=1 for one cycle. HBUS read: hen=1, hwr_rd=0 for
//   two cycles, haddr sampled on the first edge, hdata driven in the second.
// * error pulses high for one cycle 1..10 cycles after a bad-parity packet.
//
// Register / memory map (byte wide, HBUS addresses)
// ------------------------------------------------
//   0x1000 ctrl_reg              RW  reset 0x3f  [5:0] maxpktsize
//   0x1001 en_reg                RW  reset 0x01  [0] router_en, [1] parity_err_cnt_en,
//                                                [2] oversized_pkt_cnt_en, [4..7] addr0..3_cnt_en
//   0x1004 parity_err_cnt_reg    RO    0x1005 oversized_pkt_cnt_reg RO
//   0x1006 addr3_cnt_reg         RO    0x1009 addr0_cnt_reg         RO
//   0x100a addr1_cnt_reg         RO    0x100b addr2_cnt_reg         RO
//   0x100d mem_size_reg          RO  length of the last packet
//   0x1010..0x104f yapp_pkt_mem  RO  bytes of the last packet received (64 B)
//   0x1100..0x11ff yapp_mem      RW  scratch memory (256 B)
//
// Behaviour decisions where the spec is silent (keep the reference model and
// the register tests in sync with these!)
// ----------------------------------------------------------------------------
// * router_en == 0 : the input port is "deaf". The packet is tracked so the
//   FSM stays in sync, but nothing is forwarded, counted or stored.
// * A packet is DROPPED (not forwarded) when length > maxpktsize or addr == 3.
//   Dropped packets are still fully received: every enabled counter that
//   applies is incremented, parity is checked, `error` is generated, and
//   yapp_pkt_mem / mem_size_reg are updated. Thus an oversized packet to
//   address 3 increments BOTH oversized_pkt_cnt_reg and addr3_cnt_reg.
// * Changing en_reg / ctrl_reg in the middle of a packet is undefined; the
//   DUT simply uses the values present when the header is accepted.
// * `define INJECT_ERROR corrupts bit 3 of reads from yapp_mem[0x2a] so the
//   uvm_mem_walk_seq test (Lab 11B) can demonstrate a detected failure.
//------------------------------------------------------------------------------

`timescale 1ns/1ns

module yapp_router (
  input  logic        clock,
  input  logic        reset,
  // YAPP input port
  input  logic [7:0]  in_data,
  input  logic        in_data_vld,
  output logic        in_suspend,
  // Output channels
  output logic [7:0]  data_0,
  output logic        data_vld_0,
  input  logic        suspend_0,
  output logic [7:0]  data_1,
  output logic        data_vld_1,
  input  logic        suspend_1,
  output logic [7:0]  data_2,
  output logic        data_vld_2,
  input  logic        suspend_2,
  // HBUS host port
  inout  wire  [7:0]  hdata,
  input  logic [15:0] haddr,
  input  logic        hen,
  input  logic        hwr_rd,
  // Status
  output logic        error
);

  //----------------------------------------------------------------------------
  // Inter-module signals
  //----------------------------------------------------------------------------
  // register block -> input FSM
  logic [5:0] maxpktsize;
  logic       router_en;

  // input FSM -> output channels
  logic [2:0] fifo_push;
  logic [7:0] fifo_din;
  logic [2:0] fifo_full;

  // input FSM -> register block (end-of-packet report, packet memory write)
  logic       pkt_done;
  logic [1:0] pkt_addr;
  logic [5:0] pkt_len;
  logic       pkt_parity_err;
  logic       pkt_oversized;
  logic       pkt_mem_we;
  logic [5:0] pkt_mem_addr;
  logic [7:0] pkt_mem_wdata;

  // channel ports as vectors
  logic [2:0] suspend;
  logic [7:0] ch_data [0:2];
  logic [2:0] ch_data_vld;

  assign suspend    = {suspend_2, suspend_1, suspend_0};
  assign data_0     = ch_data[0];
  assign data_1     = ch_data[1];
  assign data_2     = ch_data[2];
  assign data_vld_0 = ch_data_vld[0];
  assign data_vld_1 = ch_data_vld[1];
  assign data_vld_2 = ch_data_vld[2];

  //----------------------------------------------------------------------------
  // Input port FSM
  //----------------------------------------------------------------------------
  yapp_input_fsm u_input_fsm (
    .clock          (clock),
    .reset          (reset),
    .in_data        (in_data),
    .in_data_vld    (in_data_vld),
    .in_suspend     (in_suspend),
    .maxpktsize     (maxpktsize),
    .router_en      (router_en),
    .fifo_full      (fifo_full),
    .fifo_push      (fifo_push),
    .fifo_din       (fifo_din),
    .pkt_done       (pkt_done),
    .pkt_addr       (pkt_addr),
    .pkt_len        (pkt_len),
    .pkt_parity_err (pkt_parity_err),
    .pkt_oversized  (pkt_oversized),
    .pkt_mem_we     (pkt_mem_we),
    .pkt_mem_addr   (pkt_mem_addr),
    .pkt_mem_wdata  (pkt_mem_wdata)
  );

  //----------------------------------------------------------------------------
  // Output channels (FIFO + handshake), one per address 0..2
  //----------------------------------------------------------------------------
  genvar ch;
  generate
    for (ch = 0; ch < 3; ch++) begin : g_ch
      yapp_output_channel u_ch (
        .clock    (clock),
        .reset    (reset),
        .push     (fifo_push[ch]),
        .din      (fifo_din),
        .suspend  (suspend[ch]),
        .data     (ch_data[ch]),
        .data_vld (ch_data_vld[ch]),
        .full     (fifo_full[ch])
      );
    end
  endgenerate

  //----------------------------------------------------------------------------
  // Registers, memories and HBUS host interface
  //----------------------------------------------------------------------------
  yapp_hbus_regs u_regs (
    .clock          (clock),
    .reset          (reset),
    .hdata          (hdata),
    .haddr          (haddr),
    .hen            (hen),
    .hwr_rd         (hwr_rd),
    .pkt_done       (pkt_done),
    .pkt_addr       (pkt_addr),
    .pkt_len        (pkt_len),
    .pkt_parity_err (pkt_parity_err),
    .pkt_oversized  (pkt_oversized),
    .pkt_mem_we     (pkt_mem_we),
    .pkt_mem_addr   (pkt_mem_addr),
    .pkt_mem_wdata  (pkt_mem_wdata),
    .maxpktsize     (maxpktsize),
    .router_en      (router_en)
  );

  //----------------------------------------------------------------------------
  // error pulse generator
  //----------------------------------------------------------------------------
  yapp_error_timer u_error_timer (
    .clock (clock),
    .reset (reset),
    .start (pkt_done && pkt_parity_err),
    .error (error)
  );

endmodule : yapp_router

files.yapp_project/tb/hw_top.sv:
//------------------------------------------------------------------------------
// hw_top.sv -- hardware side of the testbench (Lab 11C)
//
// The Clock & Reset UVC now owns reset, the clock period and run_clock, so the
// hand-written reset block from Lab 6 is gone.
//
// WARNING: the HBUS data bus is bidirectional. Connect the DUT to the WIRE
// `hdata_w` of the interface, never to the logic variable `hdata`.
//------------------------------------------------------------------------------
`timescale 1ns/1ns

module hw_top;

  logic clock;
  logic reset;
  logic run_clock;
  int   clock_period;

  // Clock & Reset UVC interface drives reset, run_clock and clock_period
  clock_and_reset_if clk_rst_if (
    .clock        (clock),
    .reset        (reset),
    .run_clock    (run_clock),
    .clock_period (clock_period)
  );

  // Clock generator controlled by the Clock & Reset UVC
  clkgen clkgen (.run_clock(run_clock), .clock_period(clock_period), .clock(clock));

  // Interface instances, all on the same clock and reset
  yapp_if    in0   (clock, reset);
  hbus_if    hbus0 (clock, reset);
  channel_if ch0   (clock, reset);
  channel_if ch1   (clock, reset);
  channel_if ch2   (clock, reset);

  // Status output of the router
  logic error;

  yapp_router dut (
    .clock       (clock),
    .reset       (reset),
    // YAPP input port
    .in_data     (in0.in_data),
    .in_data_vld (in0.in_data_vld),
    .in_suspend  (in0.in_suspend),
    // Output channels
    .data_0      (ch0.data),
    .data_vld_0  (ch0.data_vld),
    .suspend_0   (ch0.suspend),
    .data_1      (ch1.data),
    .data_vld_1  (ch1.data_vld),
    .suspend_1   (ch1.suspend),
    .data_2      (ch2.data),
    .data_vld_2  (ch2.data_vld),
    .suspend_2   (ch2.suspend),
    // HBUS host port
    .hdata       (hbus0.hdata_w),        // the WIRE, not hbus0.hdata
    .haddr       (hbus0.haddr),
    .hen         (hbus0.hen),
    .hwr_rd      (hbus0.hwr_rd),
    // Status
    .error       (error)
  );

endmodule : hw_top

