task channel_rx_driver::run_phase(uvm_phase phase);
  // Keep the channel suspended until reset is released
  vif.channel_reset();
  wait (vif.reset === 1'b0);
  forever begin
    seq_item_port.get_next_item(req);
    vif.receive_packet(req.delay);
    seq_item_port.item_done();
  end
