//------------------------------------------------------------------------------
// hbus_monitor.sv -- common bus monitor (one per hbus_env)
//
// Publishes every observed transaction on `item_collected_port`. Lab 9B
// connects it to the router reference model so it can mirror the register
// writes; Lab 11 uses the same traffic for the register model predictor.
//------------------------------------------------------------------------------
class hbus_monitor extends uvm_monitor;

  virtual interface hbus_if vif;

  uvm_analysis_port #(hbus_transaction) item_collected_port;

  int num_writes;
  int num_reads;

  `uvm_component_utils(hbus_monitor)

  // The fields are printed by do_print() below:
  // no uvm_field_* automation.
  extern virtual function void do_print(uvm_printer printer);
  extern function new(string name, uvm_component parent);

  extern function void connect_phase(uvm_phase phase);
  extern task run_phase(uvm_phase phase);

  extern function void report_phase(uvm_phase phase);

endclass : hbus_monitor

//------------------------------------------------------------------------------
// hbus_monitor -- method implementations
//------------------------------------------------------------------------------

function hbus_monitor::new(string name, uvm_component parent);
  super.new(name, parent);
  item_collected_port = new("item_collected_port", this);
endfunction : new

//------------------------------------------------------------------------------
function void hbus_monitor::connect_phase(uvm_phase phase);
  if (!hbus_vif_config::get(this, "", "vif", vif)) begin
    `uvm_error("NOVIF", {"virtual interface must be set for: ", get_full_name(), ".vif"})
  end
endfunction : connect_phase

//------------------------------------------------------------------------------
task hbus_monitor::run_phase(uvm_phase phase);
  hbus_transaction tr;
  bit is_write;
  @(posedge vif.clock);
  wait (vif.reset === 1'b0);
  forever begin
    tr = hbus_transaction::type_id::create("tr", this);   // new object each time
    vif.collect_transaction(tr.haddr, tr.hdata, is_write);
    tr.hwr_rd = is_write ? HBUS_WRITE : HBUS_READ;
    if (is_write) num_writes++; else num_reads++;
    `uvm_info(get_type_name(), {"Collected ", tr.convert2string()}, UVM_LOW)
    item_collected_port.write(tr);
  end
endtask : run_phase

//------------------------------------------------------------------------------
function void hbus_monitor::report_phase(uvm_phase phase);
  `uvm_info(get_type_name(),
            $sformatf("HBUS report: %0d writes, %0d reads", num_writes, num_reads), UVM_LOW)
endfunction : report_phase

//------------------------------------------------------------------------------
function void hbus_monitor::do_print(uvm_printer printer);
  super.do_print(printer);
  printer.print_field("num_writes", num_writes, $bits(num_writes), UVM_DEC);
  printer.print_field("num_reads", num_reads, $bits(num_reads), UVM_DEC);
endfunction : do_print

files.yapp_project/uvc/hbus/hbus_reg_adapter.s:
//------------------------------------------------------------------------------
// hbus_reg_adapter.sv -- translates register-model operations into HBUS
// transactions and back (Lab 11B)
//
//   reg2bus : uvm_reg_bus_op  -> hbus_transaction  (front-door access)
//   bus2reg : hbus_transaction -> uvm_reg_bus_op   (prediction / read data)
//
// provides_responses = 0 : the driver writes read data straight into the
// request item, so the register map reads it back from the same object.
//------------------------------------------------------------------------------
class hbus_reg_adapter extends uvm_reg_adapter;

  `uvm_object_utils(hbus_reg_adapter)

  extern function new(string name = "hbus_reg_adapter");
  extern virtual function uvm_sequence_item reg2bus(const ref uvm_reg_bus_op rw);

  extern virtual function void bus2reg(uvm_sequence_item bus_item, ref uvm_reg_bus_op rw);

endclass : hbus_reg_adapter

//------------------------------------------------------------------------------
// hbus_reg_adapter -- method implementations
//------------------------------------------------------------------------------

function hbus_reg_adapter::new(string name = "hbus_reg_adapter");
  super.new(name);
  supports_byte_enable = 0;
  provides_responses   = 0;
endfunction : new

//------------------------------------------------------------------------------
function uvm_sequence_item hbus_reg_adapter::reg2bus(const ref uvm_reg_bus_op rw);
  hbus_transaction tr = hbus_transaction::type_id::create("tr");
  tr.haddr  = rw.addr[15:0];
  tr.hdata  = rw.data[7:0];
  tr.hwr_rd = (rw.kind == UVM_WRITE) ? HBUS_WRITE : HBUS_READ;
  return tr;
endfunction : reg2bus

//------------------------------------------------------------------------------
function void hbus_reg_adapter::bus2reg(uvm_sequence_item bus_item, ref uvm_reg_bus_op rw);
  hbus_transaction tr;
  if (!$cast(tr, bus_item)) begin
    `uvm_fatal("NOT_HBUS_TYPE", "Provided bus_item is not of type hbus_transaction")
    return;
  end
  rw.kind   = (tr.hwr_rd == HBUS_WRITE) ? UVM_WRITE : UVM_READ;
  rw.addr   = tr.haddr;
  rw.data   = tr.hdata;
  rw.status = UVM_IS_OK;
endfunction : bus2reg

